import sys, gc
sys.path.insert(0, "/workspace")
from src.resource import Rows
from src.service import stream_rows
from src.consumer import take

class Boom(Exception): pass
class CBoom(Exception): pass

class R(Rows):
    def __init__(self, rows, read_error_at=None, close_error=None):
        super().__init__(rows); self.read_error_at=read_error_at; self.close_error=close_error
    def read_next(self):
        if self.index == self.read_error_at:
            self.reads += 1; raise Boom("r")
        return super().read_next()
    def close(self):
        super().close()
        if self.close_error: raise self.close_error

# 1. Original exception object identity is preserved (bare raise), and cleanup error is not chained onto it
err = Boom("r")
class Same(Rows):
    def read_next(self):
        self.reads += 1; raise err
    def close(self):
        super().close(); raise CBoom("c")
r = Same([1])
try:
    list(stream_rows(r, lambda v: v))
except Boom as e:
    print("1 identity preserved:", e is err, "| __context__ is None:", e.__context__ is None, "| closes:", r.closes)

# 2. GC of a started, abandoned generator closes exactly once (no double close)
r = R([1,2,3]); g = stream_rows(r, lambda v: v); next(g); del g; gc.collect()
print("2 gc close count:", r.closes, "(expect 1)")

# 3. gen.throw() at the yield point is treated as an error: closes once, propagates
r = R([1,2,3]); g = stream_rows(r, lambda v: v); next(g)
try:
    g.throw(Boom("injected"))
except Boom as e:
    print("3 throw propagated:", str(e), "closes:", r.closes)

# 4. take: the stream is closed by take itself (generator held by reference => not GC)
captured = []
import src.consumer as c
real = c.stream_rows
def spy(res, tr):
    g = real(res, tr); captured.append(g); return g
c.stream_rows = spy
r = R([1,2,3])
print("4 take result:", take(r, lambda v: v*10, 2), "closes:", r.closes, "gen finished:", captured[0].gi_frame is None)
c.stream_rows = real

# 5. take with cleanup failure on the success path propagates; with a transform error the transform error wins
r = R([1,2,3], close_error=CBoom("c"))
try: take(r, lambda v: v, 2)
except CBoom: print("5a cleanup error propagated on success path")
try: take(R([1,2,3], close_error=CBoom("c")), lambda v: 1/0 if v==2 else v, 3)
except ZeroDivisionError: print("5b transform error preserved over cleanup error")

# 6. transform error: no further read after failing row
r = R([1,2,3,4]); 
def t(v):
    if v == 2: raise Boom("t")
    return v
try: take(r, t, 4)
except Boom: print("6 reads after transform failure:", r.reads, "(expect 2)", "closes:", r.closes)

# 7. Explicit close of unstarted generator with a failing cleanup: no error and no close
r = R([1], close_error=CBoom("c")); g = stream_rows(r, lambda v: v); g.close()
print("7 unstarted close: reads", r.reads, "closes", r.closes)

# 8. Limit exactly reached on final row: no EOF read, one close
r = R([1,2]); print("8 take all rows exactly:", take(r, lambda v: v, 2), "reads", r.reads, "closes", r.closes)
